import { ai } from './ai.js';
import { lookupOrder } from './tools.js';

/** Multi-turn order desk agent: answers questions about a customer's orders with the orders database. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  description: 'Answers customers questions about the status, delivery date and tracking code of their orders.',
  system:
    'You are the Northwind Supplies order desk assistant. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so.',
  tools: [lookupOrder],
});
